package com.turboio.addon;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;

/** An isolated queue: the retired transcript/audio queues are never replayed. */
final class DailySummarySync {
 static File directory(File root,MaterialConfig config)throws IOException{File base=MaterialStorage.prepare(root,config),dir=new File(base,"daily-summaries-v1");MaterialWire.require(!Files.isSymbolicLink(dir.toPath()),"MATERIAL_LOCAL_PATH");return dir;}
 static MaterialSyncSession.Status status(File root,MaterialConfig config)throws IOException{MaterialSyncSession.Status status=new MaterialSyncSession.Status();if(config==null){status.note="unconfigured";return status;}try(MaterialOutbox queue=new MaterialOutbox(directory(root,config),config.connection)){count(status,queue);}return status;}
 private static void count(MaterialSyncSession.Status status,MaterialOutbox queue){status.queued=status.stored=status.blocked=status.expired=status.reconcile=0;Map<String,Map<String,Object>> latest=latest(queue);for(Map<String,Object> row:latest.values()){String state=(String)row.get("state");if("server_stored".equals(state))status.stored++;else if("expired".equals(state))status.expired++;else if("blocked".equals(state))status.blocked++;else status.queued++;if(Boolean.TRUE.equals(row.get("needs_lookup")))status.reconcile++;}}
 private static Map<String,Map<String,Object>> latest(MaterialOutbox queue){Map<String,Map<String,Object>> rows=new TreeMap<>();for(Object raw:queue.all()){Map<String,Object> row=WireJson.map(raw);String id=(String)row.get("material_id");MaterialWire.require(id.startsWith("daily-"),"DAILY_SUMMARY_QUEUE_INVALID");Map<String,Object> old=rows.get(id);if(old==null||MaterialWire.positive(row.get("revision"))>MaterialWire.positive(old.get("revision")))rows.put(id,row);}return rows;}
 static MaterialSyncSession.Status run(File root,MaterialConfig config,List<DailySummary> summaries,Set<String> dates,MaterialSyncSession.Guard guard,MaterialApi.Transport transport)throws Exception{
  guard.check();MaterialWire.require(config.enabled&&config.connection.expiresAt>System.currentTimeMillis(),"MATERIAL_IMPORT_EXPIRED");MaterialSyncSession.Status status=new MaterialSyncSession.Status();Set<String> allowed=new HashSet<>(),seenDates=new HashSet<>();MaterialApi api=new MaterialApi(config.connection,transport);
  try(MaterialOutbox queue=new MaterialOutbox(directory(root,config),config.connection)){Map<String,Map<String,Object>> previous=latest(queue);
   for(DailySummary summary:summaries){
    if(dates!=null&&!dates.contains(summary.date))continue;guard.check();String id=summary.id(config.account);allowed.add(id);seenDates.add(summary.date);Map<String,Object> old=previous.get(id);
    boolean missingBase=old==null||!"server_stored".equals(old.get("state"))&&MaterialWire.positive(old.get("revision"))>1&&queue.all().stream().map(WireJson::map).noneMatch(row->id.equals(row.get("material_id"))&&MaterialWire.positive(row.get("revision"))==MaterialWire.positive(previous.get(id).get("revision"))-1);
    if(missingBase){
     MaterialApi.Response response=transport.exchange("/daily-summary-head",WireJson.bytes(WireJson.object("material_id",id)));MaterialWire.require(response.status==200,"DAILY_SUMMARY_HEAD_UNAVAILABLE");Map<String,Object> found=WireJson.map(WireJson.read(response.body));BoundedJson.keys(found,"material_id","body");MaterialWire.require(id.equals(found.get("material_id")),"MATERIAL_IDENTITY_MISMATCH");
     if(found.get("body")!=null){
      Map<String,Object> remote=WireJson.map(found.get("body"));MaterialWire.body(remote);MaterialWire.require(id.equals(remote.get("material_id"))&&"agent_analysis".equals(remote.get("source"))&&WireJson.list(remote.get("utterances")).isEmpty()&&"not_retained".equals(WireJson.map(remote.get("audio")).get("state")),"MATERIAL_IDENTITY_MISMATCH");
      if(old==null){long now=System.currentTimeMillis();String eventId="daily-summary-"+UUID.randomUUID();queue.enqueue(WireJson.bytes(WireJson.object("schema_version","1.2","event_id",eventId,"idempotency_key",eventId,"kind","material.revision","producer_id",config.connection.producer,"created_at",TaskWire.now(now),"expires_at",config.connection.expires,"body",remote)));old=latest(queue).get(id);}
      Map<String,Object> pending=MaterialWire.event(((String)old.get("payload")).getBytes(StandardCharsets.UTF_8),config.connection.producer);MaterialWire.require(remote.equals(pending.get("body")),"DAILY_SUMMARY_CHANGED_PENDING");
      api.reconcileOnly(queue,(String)old.get("event_id"),System.currentTimeMillis());old=latest(queue).get(id);
      if(!"server_stored".equals(old.get("state"))){guard.check();byte[] payload=((String)old.get("payload")).getBytes(StandardCharsets.UTF_8);MaterialApi.Response stored=payload.length<=262144?transport.exchange("/material-events",payload):MaterialTransfer.send(transport,payload,pending);MaterialWire.require(stored.status==200||stored.status==201,"DAILY_SUMMARY_HEAD_UNAVAILABLE");guard.check();queue.recordAcknowledgement((String)old.get("event_id"),stored.body);old=latest(queue).get(id);}
     }else MaterialWire.require(old==null,"DAILY_SUMMARY_CHANGED_PENDING");
    }
    long revision=1;if(old!=null){Map<String,Object> body=WireJson.map(MaterialWire.event(((String)old.get("payload")).getBytes(StandardCharsets.UTF_8),config.connection.producer).get("body"));if(summary.markdown().equals(WireJson.map(body.get("full_text")).get("text")))continue;if(!"server_stored".equals(old.get("state"))){MaterialWire.require(api.cancelPending(queue,(String)old.get("event_id"),System.currentTimeMillis()),"DAILY_SUMMARY_CHANGED_PENDING");old=latest(queue).get(id);MaterialWire.require(MaterialWire.choice(old.get("state"),"server_stored","cancelled"),"DAILY_SUMMARY_CHANGED_PENDING");}revision=MaterialWire.positive(body.get("revision"))+("cancelled".equals(old.get("state"))?0:1);}
    long now=System.currentTimeMillis();String eventId="daily-summary-"+UUID.randomUUID();Map<String,Object> event=WireJson.object("schema_version","1.2","event_id",eventId,"idempotency_key",eventId,"kind","material.revision","producer_id",config.connection.producer,"created_at",TaskWire.now(now),"expires_at",config.connection.expires,"body",summary.body(config.account,revision));guard.check();queue.enqueue(WireJson.bytes(event));status.added++;
   }
   if(allowed.isEmpty())throw new IOException("DAILY_SUMMARY_NOT_READY");api.preflight(System.currentTimeMillis(),true);queue.resumeBlocked();for(int i=0;i<8;i++){guard.check();if(!api.pump(queue,System.currentTimeMillis(),allowed))break;}queue.compact();count(status,queue);status.discovered=seenDates.size();status.days=seenDates.size();status.selectedComplete=(dates==null||seenDates.containsAll(dates))&&status.queued==0&&status.blocked==0&&status.expired==0;status.progressed=status.added>0;status.note=status.selectedComplete?"server_stored":"DAILY_SUMMARY_PARTIAL";return status;
  }
 }
}
